use vstd::prelude::*;

verus! {
    // Function to calculate the minimum moves from a to b
    spec fn min_moves(a: nat, b: nat) -> nat
        requires a >= 1 && b >= 1,
    {
        if a == b {
            0
        } else if a < b {
            // To go from a to b, we need to increase
            (b - a + 1) / 2 // Each move can increase by at least 1 (odd)
        } else {
            // To go from a to b, we need to decrease
            (a - b + 1) / 2 // Each move can decrease by at least 2 (even)
        }
    }

    fn solve(input: Vec<(i8, i8)>) -> Vec<i8>
        requires input.len() <= 1000, // Assuming a reasonable limit for input size
    ensures
        result.len() == input.len(),
    {
        let mut result: Vec<i8> = Vec::new();
        for (a, b) in input.iter() {
            assert(*a >= 1 && *b >= 1); // Ensure a and b are positive
            let moves = min_moves(*a as nat, *b as nat);
            result.push(moves as i8);
        }
        result
    }
}
